    [Fact]
    public async Task TimeoutMinutes_hydrate_clamp_and_persist()
    {
        using var repo = TestRepository.Create();
        Directory.CreateDirectory(Path.Combine(repo.Root, ".relay"));
        var json = new JsonObject
        {
            ["testCmd"] = "dotnet test",
            ["logSources"] = new JsonArray(),
            ["subagentTimeoutMs"] = 3_600_000,
            ["testTimeoutMs"] = 1_200_000
        };
        var configPath = Path.Combine(repo.Root, ".relay", "config.json");
        await File.WriteAllTextAsync(configPath,
            json.ToJsonString(new JsonSerializerOptions { WriteIndented = true }) + Environment.NewLine);

        var viewModel = new MainWindowViewModel { RootPath = repo.Root };
        await viewModel.LoadInitialAsync();

        // Hydrate: ms → minutes.
        Assert.Equal(60, viewModel.StageTimeoutMinutes);
        Assert.Equal(20, viewModel.TestTimeoutMinutes);

        // Clamp below range.
        viewModel.StageTimeoutMinutes = 0;
        Assert.Equal(1, viewModel.StageTimeoutMinutes);
        viewModel.TestTimeoutMinutes = -5;
        Assert.Equal(1, viewModel.TestTimeoutMinutes);

        // Clamp above range.
        viewModel.StageTimeoutMinutes = 999;
        Assert.Equal(720, viewModel.StageTimeoutMinutes);

        // Persist valid values.
        viewModel.StageTimeoutMinutes = 45;
        viewModel.TestTimeoutMinutes = 15;
        Assert.Equal(45, viewModel.StageTimeoutMinutes);
        Assert.Equal(15, viewModel.TestTimeoutMinutes);

        // Round-trip via loader: minutes * 60000 → ms.
        var result = await RelayConfigLoader.TryLoadAsync(repo.Root);
        Assert.Equal(RelayConfigStatus.Loaded, result.Status);
        Assert.Equal(2_700_000, result.Config.SubagentTimeoutMilliseconds);
        Assert.Equal(900_000, result.Config.TestTimeoutMilliseconds);
    }
}

/// <summary>Stage timeout in minutes (1–720). Persisted as subagentTimeoutMs.</summary>
[ObservableProperty]
private int _stageTimeoutMinutes = 30;

partial void OnStageTimeoutMinutesChanged(int value)
{
    var clamped = Math.Clamp(value, 1, 720);
    if (clamped != value) { StageTimeoutMinutes = clamped; return; }
    if (Directory.Exists(RootPath))
        RelayConfigWriter.UpsertSubagentTimeout(RootPath, clamped * 60_000);
}

/// <summary>Test timeout in minutes (1–720). Persisted as testTimeoutMs.</summary>
[ObservableProperty]
private int _testTimeoutMinutes = 20;

partial void OnTestTimeoutMinutesChanged(int value)
{
    var clamped = Math.Clamp(value, 1, 720);
    if (clamped != value) { TestTimeoutMinutes = clamped; return; }
    if (Directory.Exists(RootPath))
        RelayConfigWriter.UpsertTestTimeout(RootPath, clamped * 60_000);
}

